import { ScrollView, Text, TouchableOpacity, View } from 'react-native'
import { useSafeAreaInsets } from 'react-native-safe-area-context'
import { HeaderBar } from '@/components'
import { router } from 'expo-router'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { CreditsProgressBar } from './components/CreditsProgressBar'
import {
	CreditTransactionType,
	OrganizationPlan,
	useGetAggregatedUsageByOrganizationIdQuery
} from '@/generated/graphql'
import { IntegrationItem } from './components/IntegrationItem'
import { useCurrentOrganization } from '@/utils/hooks'
import { endOfMonth, format, startOfMonth } from 'date-fns'
import { humanizeCredits } from './utils/format'
import { getPlanDisplayName } from './utils/organization'
import {
	purchaseCreditsEmitter,
	PurchaseCreditsEvents,
	upgradePlanEmitter,
	UpgradePlanEvents
} from '@/utils'
import { MotiView } from 'moti'
import { Skeleton } from 'moti/skeleton'

const USAGE_TYPE_NAMES: Partial<Record<CreditTransactionType, string>> = {
	[CreditTransactionType.GENERATION_USAGE]: 'Generations',
	[CreditTransactionType.INTEGRATION_USAGE]: 'Integrations',
	[CreditTransactionType.START_GENERATION]: 'Generations'
}

const startDate = startOfMonth(new Date())
const endDate = endOfMonth(new Date())

export const CreditsDetailScreen = ({
	balance,
	planCredits
}: {
	balance: string
	planCredits: string
}) => {
	const { theme } = useTheme()
	const insets = useSafeAreaInsets()
	const { currentOrganization } = useCurrentOrganization()

	const { data, loading } = useGetAggregatedUsageByOrganizationIdQuery({
		skip: !currentOrganization?.id,
		variables: {
			// @ts-ignore - skipping if id is null
			id: currentOrganization?.id,
			startDate: startDate.toISOString(),
			endDate: endDate.toISOString()
		}
	})

	const integrationUsage =
		data?.organizationById?.aggregatedIntegrationCreditUsageBySubType?.usages ??
		[]

	const usageByType =
		data?.organizationById?.aggregatedCreditUsageByType?.usages ?? []

	const subscriptionStartDate = currentOrganization?.subscriptionStartDate

	const onClose = () => {
		router.back()
	}

	return (
		<ScrollView
			style={styles.scrollView(theme)}
			showsVerticalScrollIndicator={false}
			contentContainerStyle={{
				paddingTop: insets.top,
				paddingBottom: insets.bottom + 16,
				gap: 32
			}}
		>
			<HeaderBar
				title="Credits"
				onClose={onClose}
				showBackButton
				showCloseButton={false}
			/>

			<View style={styles.section}>
				<View style={styles.creditUsageHeaderContainer}>
					<View style={styles.creditUsageHeader}>
						<Text style={styles.creditsUsedText(theme)}>
							{humanizeCredits(BigInt(balance))}{' '}
						</Text>
						<Text style={styles.creditsTotalText(theme)}>
							/ {humanizeCredits(BigInt(planCredits))}
						</Text>
					</View>
					<View>
						<Text style={styles.creditsUsedDescriptionText(theme)}>
							credits used this month
						</Text>
					</View>
				</View>

				<View>
					<CreditsProgressBar
						progress={1 - Number(balance) / Number(planCredits)}
					/>
				</View>

				<View style={styles.creditUsageStatsContainer}>
					{usageByType
						.filter((usage) => USAGE_TYPE_NAMES[usage.type])
						.map((usage) => (
							<View style={styles.creditUsageStatsItem} key={usage.type}>
								<Text style={styles.creditUsageStatsItemText(theme)}>
									{USAGE_TYPE_NAMES[usage.type]}:
								</Text>
								<Text style={styles.creditUsageStatsItemValueText(theme)}>
									{humanizeCredits(usage.amount)}
								</Text>
							</View>
						))}
				</View>

				<View style={styles.midSection}>
					<View style={styles.currentPlanContainer(theme)}>
						<Text style={styles.currentPlanText(theme)}>Current Plan</Text>
						<View style={styles.currentPlanBodyContainer}>
							<View style={styles.currentPlanBody}>
								<Text style={styles.currentPlanNameText(theme)}>
									{getPlanDisplayName({
										planId: currentOrganization?.planId,
										plan:
											currentOrganization?.plan ?? OrganizationPlan.FREE_USAGE
									})}
								</Text>
							</View>
							{subscriptionStartDate && (
								<Text style={styles.currentPlanBilledText(theme)}>
									billed on {format(new Date(subscriptionStartDate), 'dd')}th of
									every month
								</Text>
							)}
						</View>
						<View style={styles.currentPlanButtonsContainer}>
							<TouchableOpacity
								style={[
									styles.currentPlanButton,
									{ backgroundColor: colors[theme].gray[75] }
								]}
								onPress={() =>
									purchaseCreditsEmitter.emit(PurchaseCreditsEvents.OPEN_MODAL)
								}
							>
								<Text
									style={[
										styles.currentPlanButtonText,
										{ color: colors[theme].gray[900] }
									]}
								>
									Buy Credits
								</Text>
							</TouchableOpacity>
							<TouchableOpacity
								style={[
									styles.currentPlanButton,
									{ backgroundColor: colors[theme].gray[900] }
								]}
								onPress={() =>
									upgradePlanEmitter.emit(UpgradePlanEvents.OPEN_MODAL)
								}
							>
								<Text
									style={[
										styles.currentPlanButtonText,
										{ color: colors[theme].gray[25] }
									]}
								>
									Upgrade Plan
								</Text>
							</TouchableOpacity>
						</View>
					</View>
				</View>

				<MotiView
					transition={{ type: 'timing' }}
					style={styles.integrationsContainer}
				>
					{loading ? (
						<>
							<Skeleton width={100} height={20} />
							<View style={styles.integrationsSkeletonContainer(theme)}>
								<View style={styles.integrationsSkeletonItem}>
									<Skeleton width={28} height={28} />
									<Skeleton width={100} height={20} />
								</View>
								<Skeleton width={'100%'} height={20} />
								<Skeleton width={'100%'} height={20} />
							</View>
						</>
					) : integrationUsage.length > 0 ? (
						<>
							<Text style={styles.integrationsTitleText(theme)}>
								Integrations
							</Text>
							{integrationUsage.map((usage) => (
								<IntegrationItem key={usage.subType} usage={usage} />
							))}
						</>
					) : null}
				</MotiView>
			</View>
		</ScrollView>
	)
}

